const cfg=$('01 - Configuracao e travas').first().json;
const pages=$input.all().map(i=>i.json); const columns=[];
for(const p of pages){if(p.statusCode!==200||!Array.isArray(p.body?.value))throw Error('Schema nao confirmado');columns.push(...p.body.value);}
if(pages.at(-1).body['@odata.nextLink'])throw Error('Schema incompleto');
const byName=Object.fromEntries(columns.map(c=>[c.name,c]));
for(const f of cfg.expectedFields){const c=byName[f];if(!c||c.readOnly||!c.text)throw Error('Coluna incompatÃ­vel: '+f);}
const key=byName.Chave_Importacao;
if(key.enforceUniqueValues!==true||key.indexed!==true||key.text.maxLength!==255)throw Error('Protecao ou limite da chave mudou');
return [{json:{columns:byName,confirmed:true}}];

const pages=$input.all().map(i=>i.json);const keys=[];let empty=0;const seenLinks=new Set();
for(const p of pages){if(p.statusCode!==200||!Array.isArray(p.body?.value))throw Error('Pagina invalida: leitura incompleta');
const next=p.body['@odata.nextLink'];if(next){if(seenLinks.has(next))throw Error('Ciclo de paginacao');seenLinks.add(next);}
for(const row of p.body.value){const k=row.fields?.Chave_Importacao;if(typeof k!=='string'||!k.trim())empty++;else keys.push(k);}}
const ended=pages.length>0&&!pages.at(-1).body['@odata.nextLink'];if(!ended)throw Error('Paginacao incompleta');
return [{json:{chaves:[...new Set(keys)],totalPaginas:pages.length,totalChaveImportacao:keys.length,chavesVaziasNull:empty,chavesUnicas:new Set(keys).size,terminouSemNextLink:ended}}];

function chave(v) {
  return String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toUpperCase()
    .replace(/\s+/g, ' ');
}

function texto(v) {
  return String(v ?? '')
    .trim()
    .replace(/\s+/g, ' ');
}

function excelDate(v) {
  if (v === null || v === undefined || v === '') return '';

  const n = Number(v);

  if (!Number.isFinite(n)) {
    return texto(v);
  }

  const base = Date.UTC(1899, 11, 30);
  const data = new Date(base + n * 86400000);

  return data.toISOString().slice(0, 10);
}

function codigo(v) {
  const s = String(v ?? '').trim();

  // Na planilha de origem, 0 representa ausÃªncia de cÃ³digo.
  return s === '0' ? '' : s;
}

return items.map(item => {
  const j = item.json;

  const chaveImportacao = [
    'NEOENERGIA_REDE',
    chave(codigo(j['Codigo_SAP_EKT'])),
    chave(codigo(j['Codigo_SAP_NE'])),
    chave(codigo(j['Codigo_SAP_NDB'])),
    chave(j['Descricao_Sucinta']),
    chave(j['Espec_Tecnica']),
    chave(j['Refer_Fornecedor']),
    chave(j['Fornec_razao_social'])
  ].join('|');

  return {
    json: {
      Title: texto(j['Descricao_Sucinta']),

      Codigo_Nordeste: codigo(j['Codigo_SAP_NE']),
      Codigo_Elektro: codigo(j['Codigo_SAP_EKT']),
      Codigo_Brasilia: codigo(j['Codigo_SAP_NDB']),

      Familia: texto(j['Familia']),
      SubFamilia: '',

      Descricao: texto(j['Descricao_Sucinta']),
      Descricao_Completa: texto(j['Descricao_Completa']),

      Especificacao_Tecnica: texto(j['Espec_Tecnica']),
      Refer_Fornecedor: texto(j['Refer_Fornecedor']),
      Desenho_Fornecedor: texto(j['Desenho_Fornecedor']),

      Fornecedor: texto(j['Fornec_razao_social']),
      CNPJ: texto(j['CNPJ']),

      Data_Homologacao: excelDate(j['Data_homologacao']),
      Data_Vencimento_Homologacao: excelDate(j['Data_venc_homolog']),

      Ref_Documentacao: texto(j['Ref_Documentacao']),
      Modo_Fornecimento: texto(j['Modo_fornec']),
      CA: texto(j['CA']),
      Observacao: texto(j['Observacao']),

      Tipo_Gestao_Recebimento: texto(
        j['Tipo de GestÃ£o de Recebimento']
      ),

      Status_Homologacao: '',
      Nome_Normalizado: '',

      Fonte: 'NEOENERGIA_REDE',

      Numero_Patrimonio_Nordeste: '',
      Numero_Patrimonio_Elektro: '',
      Numero_Patrimonio_Brasilia: '',

      Chave_Importacao: chaveImportacao
    }
  };
});

const rows = $input.all();
const catalog = $('05 - SharePoint - Consolidar chaves').first().json;
const existing = new Set(catalog.chaves);
const counts = new Map();
let empty = 0;
let existingRows = 0;
let missingRows = 0;
for (const item of rows) {
  const key = item.json.Chave_Importacao;
  if (key === null || key === undefined || String(key).trim() === '') {
    empty++;
    continue;
  }
  counts.set(key, (counts.get(key) || 0) + 1);
  if (existing.has(key)) existingRows++;
  else missingRows++;
}
const duplicates = [...counts].filter(([, count]) => count > 1);
const missing = [...counts.keys()].filter(key => !existing.has(key));
return [{ json: {
  totalItensRedeLidos: $('11 - Rede - Extrair D10 U22953').all().length,
  totalItensPreparados: rows.length,
  totalChavesGeradas: rows.length - empty,
  chavesVaziasNull: empty,
  chavesUnicasRede: counts.size,
  chavesDistintasDuplicadas: duplicates.length,
  ocorrenciasDuplicadasExcedentes: rows.length - empty - counts.size,
  linhasEmGruposDuplicados: duplicates.reduce((sum, [, count]) => sum + count, 0),
  chavesExistentesSharePoint: existing.size,
  paginasSharePoint: catalog.totalPaginas,
  terminouSemNextLink: catalog.terminouSemNextLink,
  linhasJaExistentesSharePoint: existingRows,
  chavesUnicasJaExistentesSharePoint: counts.size - missing.length,
  linhasAusentesSharePoint: missingRows,
  chavesUnicasAusentesParaPost: missing.length,
  exemplosAusentes: missing.slice(0, 5),
  exemplosDuplicadas: duplicates.slice(0, 5).map(([chave, ocorrencias]) => ({ chave, ocorrencias }))
} }];

const existing = new Set($('05 - SharePoint - Consolidar chaves').first().json.chaves);
const seen = new Set();
const result = [];
for (const [index, item] of $input.all().entries()) {
  const key = item.json.Chave_Importacao;
  if (key === null || key === undefined || String(key).trim() === '') continue;
  if (seen.has(key)) continue;
  seen.add(key);
  if (existing.has(key)) continue;
  result.push({ json: item.json, pairedItem: { item: index } });
}
return result;

const candidates = $input.all();

const validos = [];
let bloqueados = 0;

for (const item of candidates) {
  const key = String(item.json.Chave_Importacao ?? '');

  if (!key || key.length > 255) {
    bloqueados++;
    continue;
  }

  validos.push({
    json: {
      ...item.json
    }
  });
}

// SEGURANÃ‡A INICIAL:
// somente 5 registros seguem para a carga.
return validos.slice(0, 450);

